    /// The prior centre's sign of (need, col): 1, -1 or 0 for an obvious pair;
    /// `isObvious` false (and 0) otherwise.
    struct Prior
    {
        bool isObvious = false;
        std::int8_t sign = 0;
    };

    [[nodiscard]] constexpr Prior PriorOf(Needs::NeedId need, Effect::Col col) noexcept
    {
        for (const auto& p : kPairs) {
            if (p.need == need && p.col == col) return Prior{ true, p.sign };
        }
        return Prior{};
    }
